pub fn remove_times(&mut self, val: &K, times: usize) -> usize {
    if let Some(count) = self.elem_counts.get_mut(val) {
        let to_remove = (*count).min(times);
        *count -= to_remove;
        if *count == 0 {
            self.elem_counts.remove(val);
        }
        to_remove
    } else {
        0
    }
}
